{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Mithramycin, a glycosylated anticancer polyketide, achieved only a 0.12 CSF:plasma ratio and little brain uptake in monkeys; doxorubicin is the same general class of large glycosidic anticancer drug, supporting poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Erythromycin, a large glycosylated macrolide, showed poor CSF penetration even in meningitis, indicating that large polar glycosides do not achieve meaningful CNS access despite barrier disruption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Loganin, a glycoside, had the lowest brain levels after systemic administration in rats, consistent with poor BBB crossing for glycosylated polar natural products.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin showed very low CSF/plasma ratios (0.01-0.03), demonstrating that glycoside drugs are largely excluded from the CNS.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "low",
  "decision_summary": "Doxorubicin is a large polar anthracycline glycoside with known P-gp efflux; cyclosporine may reduce efflux, but the consistent poor CNS penetration of analogous glycosides and doxorubicin's low passive permeability indicate CNS access would remain inadequate.",
  "evidence_gaps": [
    "No direct experimental record for doxorubicin with cyclosporine co-treatment; brain/plasma or CSF data under P-gp inhibition are absent.",
    "The available records are for other glycosides without cyclosporine co-treatment, so the magnitude of P-gp inhibition on doxorubicin CNS exposure is inferred, not measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

